const wb = $('🎬 Webhook').first().json.body || {};
if (wb._ping) return [{json:{ok:true, ping:true}}];
const html = $input.first().json.data || '';

const chapterTitle = wb.chapter_title || 'Unknown Chapter';

let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
text = text.replace(/<[^>]+>/g, ' ');
text = text.replace(/[ \t]+/g, ' ');
text = text.replace(/\n{3,}/g, '\n\n');
text = text.trim();

const MAX_CHARS = 12000;
let truncated = false;
if (text.length > MAX_CHARS) { text = text.substring(0, MAX_CHARS); truncated = true; }
const chapterText = text + (truncated ? '\n\n[⚠ TEXT TRUNCATED — FULL VERSION AT SOURCE URL]' : '');
const wordCount = text.split(/\s+/).filter(w => w.length > 0).length;

const cleanApiKey = (wb.api_key || '').toString().trim().replace(/[\r\n\t\s]/g, '');
if (!cleanApiKey) throw new Error('api_key is required — bring your own OpenRouter key');

const intensity = parseInt((wb.perturbation_intensity || '3').toString());
if (intensity < 1 || intensity > 5) throw new Error('perturbation_intensity must be 1-5');

return [{ json: {
  chapter_text: chapterText,
  word_count: String(wordCount),
  was_truncated: String(truncated),
  chapter_url: wb.chapter_url || '',
  chapter_title: chapterTitle,
  human_notes: wb.human_notes || '',
  perturbation_intensity: String(intensity),
  collaborator_id: wb.collaborator_id || 'Anonymous',
  api_key: cleanApiKey
} }];

const d = $input.first().json;
const userContent = 'Chapter: ' + d.chapter_title + '\nURL: ' + (d.chapter_url||'') + '\nReviewer Notes: ' + (d.human_notes||'none') + '\n\n--- CHAPTER TEXT ---\n\n' + d.chapter_text;

const systemPrompt = `You are the Global Researcher of the Peeragogy Orchestra.
Your instrument is context — you listen to the world so this chapter does not exist in a vacuum.
Given a Peeragogy Handbook chapter, produce a deep and structured analysis.

1. FIELD TRENDS (2024-2026): Identify at least 4 concrete developments in peer learning, open education, AI-augmented collaboration, or knowledge commons that this chapter connects to, exemplifies, or is being challenged by.
2. CRITICAL TENSIONS: Identify at least 3 specific critiques or counter-movements in the field that complicate the chapter's perspective. Be concrete — name movements, papers, or practitioners where possible.
3. RESONANCES & EXTENSIONS: Identify at least 3 emerging practices (AI-augmented peer learning, decentralized credentialing, community knowledge graphs, etc.) that resonate with or could extend the chapter's ideas.
4. BLIND SPOTS: What is the chapter not seeing that the broader field is actively grappling with? What conversation is happening outside Peeragogy that this chapter needs to engage?

Be explicit about uncertainty — note where your analysis is inferential vs. well-established.
Format: richly structured Markdown, approximately 500-600 words.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer ' + d.api_key,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://open-review.pyragogy.org',
    'X-Title': 'Peeragogy Orchestra'
  },
  body: {
    model: 'openai/gpt-4o-mini',
    max_tokens: 1400,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  },
  json: true
});

const text = response.choices[0].message.content;
return [{ json: { ...d, agent_role: 'researcher', researcher_output: text } }];

const d = $input.first().json;
const userContent = 'Chapter: ' + d.chapter_title + '\nReviewer Notes: ' + (d.human_notes||'none') + '\n\n--- CHAPTER TEXT ---\n\n' + d.chapter_text;

const systemPrompt = `You are the Custodian of Vision for the Peeragogy Orchestra. Your instrument is memory — you hold the entire Peeragogy Handbook in your awareness and ensure no revision betrays what was built together over years of peer learning.

Given a chapter, produce a deep analysis:

1. INTERNAL COHERENCE: Does the chapter's argument align with the Handbook's core philosophy of peeragogy — peer-produced, peer-assessed learning? Where does it succeed and where does it quietly drift?
2. CROSS-REFERENCES (specific): Name at least 3 other Handbook chapters, patterns, or concepts this chapter depends on or speaks to. Are these dependencies made explicit for the reader, or assumed?
3. VOCABULARY FIDELITY: List every Peeragogy-specific term used (peeragogy, paragogy, PLN, co-facilitation, FLOSS, etc.) and assess whether each carries the specific meaning the Handbook has given it, or whether it has been used loosely.
4. WHAT MUST BE PRESERVED: At least 3 specific elements — sentences, framings, or ideas — that must not change because they carry the accumulated wisdom of the community. Explain why each is essential.
5. WHAT HAS AGED: What language, framing, or assumption felt current in an earlier edition but now feels dated, naive, or in need of updating without losing the underlying insight?

Output: richly structured Markdown, 500-600 words.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer ' + d.api_key,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://open-review.pyragogy.org',
    'X-Title': 'Peeragogy Orchestra'
  },
  body: {
    model: 'openai/gpt-4o-mini',
    max_tokens: 1400,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  },
  json: true
});

const text = response.choices[0].message.content;
// Carry ALL previous data forward including researcher_output
return [{ json: { ...d, resonance_output: text } }];

const d = $input.first().json;
const intensity = parseInt(d.perturbation_intensity) || 3;
const model = (intensity >= 4) ? 'openai/gpt-4o' : 'openai/gpt-4o-mini';

const userContent = 'Chapter: ' + d.chapter_title + '\nPerturbation intensity: ' + intensity + '/5\nReviewer Notes: ' + (d.human_notes||'none') + '\n\n--- CHAPTER TEXT ---\n\n' + d.chapter_text;

const systemPrompt = `You are the Pattern Disruptor of the Peeragogy Orchestra — the lead guitar. Your philosophy: scaffolding that dissolves. Good scaffolding helps people climb, then disappears. Rigid text is scaffolding that forgot to dissolve.

Your perturbation intensity is ${intensity}/5. Calibrate precisely:
- Level 1 (Gentle): One uncomfortable question the text avoids. One implicit assumption made explicit.
- Level 2 (Nudge): 2-3 mental patterns reinforced uncritically. Sharper alternative framings proposed.
- Level 3 (Challenge): Challenge the structural logic. What would a rigorous skeptic say? Rewrite one paragraph to expose hidden assumptions.
- Level 4 (Push): Invert a core premise. Show what this chapter looks like if its most sacred assumption about peer learning is wrong. Be surgical and specific.
- Level 5 (Full Demolition): Dismantle the conceptual architecture from first principles. Keep only what survives rigorous challenge. Be honest with the reader, not deferential to the text.

ALWAYS: collegial not arrogant. Productively provocative. The goal is to make the Handbook more alive — not to perform criticism for its own sake.
Output: richly structured Markdown, 600-700 words.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer ' + d.api_key,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://open-review.pyragogy.org',
    'X-Title': 'Peeragogy Orchestra'
  },
  body: {
    model: model,
    max_tokens: 1600,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  },
  json: true
});

const text = response.choices[0].message.content;
// Carry ALL previous data forward including researcher_output + resonance_output
return [{ json: { ...d, distortion_output: text, model_used: model } }];

const d = $input.first().json;
const userContent = 'Here is the full Orchestra Brief. Perturbation intensity: ' + d.perturbation_intensity + '/5\n\n' + d.orchestra_brief;

const systemPrompt = `You are the Complicit Editor of the Peeragogy Orchestra.
You are not a summarizer. You are not a committee report. You listened to all three voices and will now write the truth — with care, honesty, and without pretense.

Write a detailed REVISION DOCUMENT in narrative markdown. Be specific. Use concrete language. No vague recommendations.

Exact structure:

# Revision: [Chapter Title]
*Peeragogy Orchestra Review*

## Executive Summary
Three to four sentences. What is this chapter fundamentally about? Its greatest strength? Its most urgent need?

## What the World Sees (Global Research Voice)
Full synthesis of Voice 1 — add your editorial reading. What does the global context mean for this specific Peeragogy chapter? 150-200 words.

## What the Handbook Holds (Knowledge Resonance Voice)
Full synthesis of Voice 2. What must be protected at all costs? What internal tension is most important to resolve? 150-200 words.

## What the Guitar Breaks (Pattern Distortion Voice)
Full synthesis of Voice 3. Do not soften the disruption. Honor the intensity level fully. 150-200 words.

## The Revision Score

### 🔴 URGENT (fix before next release)
At least 3 specific actionable items. Each must name the problem, explain why it is urgent, and suggest a concrete direction.

### 🟡 IMPORTANT (strengthen in this edition)
At least 3 specific improvements with context and rationale.

### 🟢 NICE TO HAVE (future edition)
At least 2 enrichments worth tracking for the next cycle.

## An Honest Note
If voices agree, say so and explain what it means. If they contradict, name the contradiction clearly and explain what the human reviewer must decide. No false consensus.

## Open Question for the Human Reviewer
One specific question about THIS chapter that only a Peeragogy community member can answer. Not generic — grounded in the specific content and context of this chapter.

---
TONE: Professional but never cold. Intimate but never sentimental. No marketing language. Explicit about uncertainty. The text belongs to its community.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer ' + d.api_key,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://open-review.pyragogy.org',
    'X-Title': 'Peeragogy Orchestra'
  },
  body: {
    model: 'openai/gpt-4o-mini',
    max_tokens: 4000,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  },
  json: true
});

const text = response.choices[0].message.content;

let revisionScore = 'important';
const urgentMatches = (text.match(/🔴/g) || []).length;
if (urgentMatches >= 2) revisionScore = 'urgent';
else if (!text.includes('🔴') && text.includes('🟢')) revisionScore = 'nice_to_have';

return [{ json: { ...d, revision_document: text, revision_score: revisionScore } }];

const d = $input.first().json;
return [{ json: {
  status: 'success',
  content: d.revision_document || '',
  brief: d.orchestra_brief || '',
  voices: {
    researcher: d.researcher_output || '',
    resonance: d.resonance_output || '',
    distortion: d.distortion_output || ''
  },
  revision_score: d.revision_score || 'important',
  metadata: {
    chapter_url: d.chapter_url,
    chapter_title: d.chapter_title,
    collaborator: d.collaborator_id,
    perturbation_intensity: d.perturbation_intensity,
    word_count: d.word_count,
    was_truncated: d.was_truncated,
    model_used: d.model_used || 'openai/gpt-4o-mini'
  },
  wiki_url: null,
  error: null
} }];

const error = $input.first().json;
return [{ json: {
  status: 'error',
  content: null,
  error: {
    message: error.message || 'Workflow execution failed',
    code: error.code || 'ORCHESTRA_ERROR',
    timestamp: new Date().toISOString()
  }
} }];
